const KEY='<JWT_REDACTED>';
const GKEY='AIzaSyBgy0UWp2oEid5m5HJqwx7J1q9XL2D2WJ0';
const NL=String.fromCharCode(10);
let subs=[]; try{ subs=await this.helpers.httpRequest({method:'GET',url:'https://zkylrolpuwybsksspblj.supabase.co/rest/v1/casas_subscribers?select=email,name',headers:{apikey:KEY,Authorization:'Bearer '+KEY},json:true}); }catch(e){ subs=[]; }
let tpl=''; try{ tpl=await this.helpers.httpRequest({method:'GET',url:'https://andreytry.github.io/hotel-concierge-demo/newsletter.html'}); }catch(e){ tpl=''; }
if(typeof tpl!=='string'){ tpl=String(tpl); }
let eventsText='';
try{
  const gbody={ contents:[{parts:[{text:'Give exactly 3 short items of what is happening in Miami, Florida this week (events, sports such as the FIFA World Cup at Hard Rock Stadium, festivals, notable things to do). Format each item on its own line as: Title | one short sentence. No preamble, no numbering, no markdown.'}]}], tools:[{google_search:{}}], generationConfig:{temperature:0.4} };
  const gr=await this.helpers.httpRequest({method:'POST',url:'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key='+GKEY,body:gbody,json:true});
  const parts=(gr && gr.candidates && gr.candidates[0] && gr.candidates[0].content && gr.candidates[0].content.parts)||[];
  eventsText=parts.map(function(p){return p.text;}).filter(Boolean).join(' ');
}catch(e){ eventsText=''; }
function row(title,desc,last){ const b= last? '' : 'border-bottom:1px solid rgba(10,22,38,.12);'; return '<tr><td style="padding:14px 0;'+b+'"><div style="font-family:Georgia,serif;font-size:19px;color:#0a1626;">'+title+'</div><div style="font-size:13.5px;color:#6f7789;margin-top:3px;">'+desc+'</div></td></tr>'; }
let rows='';
const lines=(eventsText||'').split(NL).map(function(x){return x.trim();}).filter(function(x){return x.indexOf('|')>0;});
if(lines.length>0){ const use=lines.slice(0,3); use.forEach(function(l,i){ const pp=l.split('|'); rows+=row(pp[0].trim(), (pp[1]||'').trim(), i===use.length-1); }); }
else { rows=row('The FIFA World Cup is in town','Matches at Hard Rock Stadium, about 11 miles from your door.',false)+row('Sunset at Bayfront Park','A three-minute walk away, best just before eight.',false)+row('A day across the causeway','South Beach is fifteen minutes away.',true); }
const out=[];
for(const s of (Array.isArray(subs)?subs:[])){ if(!s||!s.email) continue; const first=((s.name||'there')+'').split(' ')[0]; let html=tpl.split('{{first_name}}').join(first).split('{{events_html}}').join(rows); out.push({json:{to:s.email,first:first,subject:'Your weekly note from The Casas Collection',html:html}}); }
if(out.length===0){ out.push({json:{to:'andrewtry002@gmail.com',first:'there',subject:'Your weekly note from The Casas Collection',html:tpl.split('{{events_html}}').join(rows)}}); }
return out;
